@Composable
fun CounterScreen() {
    var count by remember { mutableIntStateOf(0) }
    Counter(value = count, onIncrement = { count++ })
}

@Composable
fun Counter(value: Int, onIncrement: () -> Unit) {
    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text("Count: $value", style = MaterialTheme.typography.headlineMedium)
        Button(onClick = onIncrement) { Text("Incrementar") }
    }
}

@Composable
fun UserCard(user: User) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = Modifier.fillMaxWidth().padding(12.dp),
    ) {
        AsyncImage(
            model = user.avatarUrl,
            contentDescription = null,
            modifier = Modifier.size(48.dp).clip(CircleShape),
        )
        Spacer(Modifier.width(12.dp))
        Column(Modifier.weight(1f)) {
            Text(user.name, fontWeight = FontWeight.SemiBold)
            Text(user.email, color = MaterialTheme.colorScheme.onSurfaceVariant)
        }
        Icon(Icons.Default.ChevronRight, contentDescription = null)
    }
}

@Composable
fun UserList(users: List<User>, onClick: (User) -> Unit) {
    LazyColumn {
        items(users, key = { it.id }) { user ->
            UserCard(user = user)
                .also { /* decorativo: acoes via modifier clickable */ }
        }
    }
}

data class UsersUiState(
    val loading: Boolean = false,
    val users: List<User> = emptyList(),
    val error: String? = null,
)

class UsersViewModel(private val repo: UserRepo) : ViewModel() {
    private val _state = MutableStateFlow(UsersUiState())
    val state: StateFlow<UsersUiState> = _state.asStateFlow()

    init { load() }

    fun load() = viewModelScope.launch {
        _state.update { it.copy(loading = true, error = null) }
        runCatching { repo.all() }
            .onSuccess { list -> _state.update { it.copy(loading = false, users = list) } }
            .onFailure { t -> _state.update { it.copy(loading = false, error = t.message) } }
    }
}

@Composable
fun UsersScreen(vm: UsersViewModel = hiltViewModel()) {
    val ui by vm.state.collectAsStateWithLifecycle()
    when {
        ui.loading      -> LoadingIndicator()
        ui.error != null -> ErrorView(ui.error)
        else            -> UserList(users = ui.users, onClick = {})
    }
}

@Composable
fun AppNav() {
    val nav = rememberNavController()
    NavHost(navController = nav, startDestination = "users") {
        composable("users") {
            UsersScreen(onUserClick = { id -> nav.navigate("user/$id") })
        }
        composable(
            route = "user/{id}",
            arguments = listOf(navArgument("id") { type = NavType.LongType }),
        ) { backStack ->
            val id = backStack.arguments?.getLong("id") ?: return@composable
            UserDetailScreen(id = id)
        }
    }
}

@Composable
fun AppTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit,
) {
    val colorScheme = if (darkTheme) darkColorScheme() else lightColorScheme()
    MaterialTheme(
        colorScheme = colorScheme,
        typography = AppTypography,
        content = content,
    )
}

